import{_ as t,o as i,c as s,a2 as e}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"音频资产","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/audio-assets.md","filePath":"authoring/audio-assets.md","lastUpdated":null}'),l={name:"authoring/audio-assets.md"};function d(n,a,h,o,r,p){return i(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="音频资产" tabindex="-1">音频资产 <a class="header-anchor" href="#音频资产" aria-label="Permalink to &quot;音频资产&quot;">​</a></h1><p>人工录音用于听力课、长短语和对话。单词与短表达保持运行时 TTS，不为每个词捆绑独立录音。</p><h2 id="格式" tabindex="-1">格式 <a class="header-anchor" href="#格式" aria-label="Permalink to &quot;格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>要求</th></tr></thead><tbody><tr><td>容器</td><td>MP3</td></tr><tr><td>采样率</td><td>44.1 kHz</td></tr><tr><td>声道</td><td>单声道优先，接受立体声</td></tr><tr><td>比特率</td><td>至少 128 kbps</td></tr><tr><td>前后静音</td><td>各不超过 0.3 秒</td></tr></tbody></table><h2 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to &quot;路径&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assets/sounds/turkish/listening/</span></span></code></pre></div><p>文件名必须与课程 JSON 中 <code>audioAsset</code> 的标识符一致并加 <code>.mp3</code>。不要仅添加文件而不更新引用，也不要仅添加引用而不提交文件。</p><p><code>bgm/</code>、<code>debut/</code> 和 <code>fin/</code> 用于听力节目格式的混音资产。普通人工对话录音放在 listening 根目录。</p><h2 id="录音要求" tabindex="-1">录音要求 <a class="header-anchor" href="#录音要求" aria-label="Permalink to &quot;录音要求&quot;">​</a></h2><ul><li>使用土耳其语母语者或达到流利程度的说话者。</li><li>环境噪声保持低且稳定。</li><li>麦克风距离约 10–20 cm，并控制爆破音。</li><li>使用自然、清晰、面向学习者的速度。</li><li>不使用夸张语调。</li><li>峰值不得削波。</li><li>不包含未经许可的音乐或第三方内容。</li></ul><h2 id="替换生成音频" tabindex="-1">替换生成音频 <a class="header-anchor" href="#替换生成音频" aria-label="Permalink to &quot;替换生成音频&quot;">​</a></h2><p>人工录音可以覆盖同 ID 的 TTS 生成文件。提交说明中标记替换关系。ID 保持不变，因此 Lesson JSON 无需因音质替换而修改。</p><h2 id="校验" tabindex="-1">校验 <a class="header-anchor" href="#校验" aria-label="Permalink to &quot;校验&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool/course_cli.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --course-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/courses/turkish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool/course_cli.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audio-manifest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/manifest.csv</span></span></code></pre></div><p>检查清单：</p><ul><li>资产在 manifest 中出现。</li><li>JSON 引用与文件名一致。</li><li>文件可在目标设备解码。</li><li>音量与相邻素材接近。</li><li>无超长静音。</li><li>听力题有重播和必要文本边界。</li></ul><h2 id="授权" tabindex="-1">授权 <a class="header-anchor" href="#授权" aria-label="Permalink to &quot;授权&quot;">​</a></h2><p>提交者必须拥有录音版权或授权，并允许项目长期、免版税地随 Turna 分发。录音不得包含未授权背景音乐。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/audio-and-tts">音频、TTS 与朗读</a></li><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/authoring/release-checklist">发布检查表</a></li></ul>`,20)])])}const k=t(l,[["render",d]]);export{u as __pageData,k as default};
